function projectAccent(name: string): string {
  const hues = [200, 240, 160, 280, 20, 340, 60, 300]
  let h = 0
  for (let i = 0; i < name.length; i++)
    h = (h * 31 + name.charCodeAt(i)) & 0xfffffff
  return `hsl(${hues[h % hues.length]}deg 35% 16%)`
}

